<script setup lang="ts">
import { computed, nextTick, onMounted, ref } from 'vue'
import { Activity, ArrowDownRight, ArrowLeftRight, ArrowUpRight, BriefcaseBusiness, CalendarDays, Check, ChevronDown, ChevronRight, CircleHelp, Clock3, Download, ExternalLink, FileUp, Globe2, LayoutDashboard, LoaderCircle, MoreHorizontal, Plus, Search, Settings2, ShieldCheck, SlidersHorizontal, Sparkles, TrendingUp, Upload, Wallet, X } from 'lucide-vue-next'

type Trade={id:number;symbol:string;name:string;market:'JP'|'US';currency:'JPY'|'USD';side:'BUY'|'SELL';trade_date:string;quantity:number;price:number;fee:number;target_price:number|null;asset_type:'STOCK'|'FUND'|'CASH';entry_type:'TRADE'|'OPENING'}
type Position={symbol:string;name:string;market:'JP'|'US';currency:'JPY'|'USD';quantity:number;basis:number;target_price:number|null;average_cost:number;asset_type:'STOCK'|'FUND'|'CASH'}
type Quote={symbol:string;currency:string;price:number;change_pct:number|null;fetched_at:string;source:string}
type Snap={day:string;value_jpy:number;recorded_at:string}
const trades=ref<Trade[]>([]), positions=ref<Position[]>([]), quotes=ref<Quote[]>([]), snapshots=ref<Snap[]>([])
const keyState=ref(false), apiKey=ref(''), loading=ref(true), refreshing=ref(false), toast=ref(''), modal=ref(false), settingsOpen=ref(false), csvInput=ref<HTMLInputElement>(), backupInput=ref<HTMLInputElement>(), search=ref(''), period=ref('1M'), page=ref('overview')
const todayParts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tokyo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date())
const today=`${todayParts.find(x=>x.type==='year')?.value}-${todayParts.find(x=>x.type==='month')?.value}-${todayParts.find(x=>x.type==='day')?.value}`
const blankForm=()=>({symbol:'',name:'',market:'JP' as 'JP'|'US',currency:'JPY' as 'JPY'|'USD',side:'BUY' as 'BUY'|'SELL',trade_date:today,quantity:'',price:'',fee:'0',target_price:'',asset_type:'STOCK' as 'STOCK'|'FUND'|'CASH',entry_type:'TRADE' as 'TRADE'|'OPENING'})
const form=ref(blankForm()), editing=ref<number|null>(null), formError=ref('')
const priceModal=ref(false), pricePosition=ref<Position|null>(null), manualPrice=ref('')
const quoteMap=computed(()=>new Map(quotes.value.map(q=>[`${q.symbol}:${q.currency}`,q])))
const fx=computed(()=>quoteMap.value.get('USD/JPY:FX')?.price||0)
const computedPositions=computed(()=>positions.value.map(p=>{const q=quoteMap.value.get(`${p.symbol}:${p.currency}`);const price=q?.price??0;const value=price*p.quantity/(p.asset_type==='FUND'?10000:1);const cost=p.basis;const pnl=value-cost;const pct=cost?pnl/cost*100:0;return {...p,price,value,cost,pnl,pct,quote:q}}).filter(p=>p.quantity>0))
const totalValue=computed(()=>computedPositions.value.reduce((s,p)=>s+(p.currency==='USD'?p.value*fx.value:p.value),0))
const totalCost=computed(()=>computedPositions.value.reduce((s,p)=>s+(p.currency==='USD'?p.cost*fx.value:p.cost),0))
const totalPnl=computed(()=>totalValue.value-totalCost.value)
const totalPct=computed(()=>totalCost.value?totalPnl.value/totalCost.value*100:0)
const capturedAt=computed(()=>quotes.value.reduce((latest,q)=>q.fetched_at>latest?q.fetched_at:latest,''))
const filtered=computed(()=>computedPositions.value.filter(p=>`${p.name} ${p.symbol}`.toLowerCase().includes(search.value.toLowerCase())))
const filteredTrades=computed(()=>[...trades.value].slice(0,7))
const holdingCount=computed(()=>computedPositions.value.length)
const chartPoints=computed(()=>{
 const rows=snapshots.value; if(!rows.length)return []
 const cutoff=new Date(); if(period.value==='1W')cutoff.setDate(cutoff.getDate()-7);else if(period.value==='1M')cutoff.setMonth(cutoff.getMonth()-1);else if(period.value==='3M')cutoff.setMonth(cutoff.getMonth()-3);else cutoff.setFullYear(cutoff.getFullYear()-1)
 const filteredRows=rows.filter(x=>new Date(x.day)>=cutoff); return filteredRows.length>1?filteredRows:rows
})
const chartPath=computed(()=>{const a=chartPoints.value;if(a.length<2)return '';const lo=Math.min(...a.map(x=>x.value_jpy)),hi=Math.max(...a.map(x=>x.value_jpy));return a.map((p,i)=>`${i?'L':'M'} ${(i/(a.length-1))*100} ${(hi===lo?50:95-(p.value_jpy-lo)/(hi-lo)*85)}`).join(' ')})
const chartArea=computed(()=>chartPath.value?`${chartPath.value} L 100 100 L 0 100 Z`:'')
const chartChange=computed(()=>chartPoints.value.length>1?chartPoints.value.at(-1)!.value_jpy-chartPoints.value[0]!.value_jpy:0)
const markets=[{symbol:'SPY',name:'米国大型株',region:'UNITED STATES',flag:'🇺🇸',currency:'USD'},{symbol:'QQQ',name:'米国テック株',region:'NASDAQ 100 PROXY',flag:'◉',currency:'USD'},{symbol:'EWJ',name:'日本株',region:'JAPAN EQUITY PROXY',flag:'🇯🇵',currency:'USD'},{symbol:'VGK',name:'欧州株',region:'EUROPE EQUITY PROXY',flag:'🇪🇺',currency:'USD'}]
const colors=['#638c6b','#8b7dc2','#e2a46a','#7b9ab8','#cc7d78']
const donutStyle=computed(()=>{let cursor=0;const slices=computedPositions.value.map((p,i)=>{const share=totalValue.value?(p.value*(p.currency==='USD'?fx.value:1))/totalValue.value*100:0;const from=cursor;cursor+=share;return `${colors[i%colors.length]} ${from}% ${cursor}%`});return {background:slices.length?`conic-gradient(${slices.join(',')})`:'conic-gradient(#e7e9e6 0 100%)'}})
const formatMoney=(n:number,currency='JPY',compact=false)=>new Intl.NumberFormat('ja-JP',{style:'currency',currency,notation:compact?'compact':'standard',maximumFractionDigits:currency==='JPY'?0:2}).format(Number.isFinite(n)?n:0)
const formatYen=(n:number,compact=false)=>new Intl.NumberFormat('ja-JP',{style:'currency',currency:'JPY',notation:compact?'compact':'standard',maximumFractionDigits:0}).format(Number.isFinite(n)?n:0)
const formatNum=(n:number,d=2)=>new Intl.NumberFormat('ja-JP',{maximumFractionDigits:d}).format(n)
const formatDate=(s:string)=>s?new Intl.DateTimeFormat('ja-JP',{year:'numeric',month:'short',day:'numeric'}).format(new Date(s)):''
const since=(s:string)=>{if(!s)return '未取得';const d=Math.max(0,Math.floor((Date.now()-new Date(s).getTime())/60000));return d<1?'たった今':d<60?`${d}分前`:d<1440?`${Math.floor(d/60)}時間前`:formatDate(s)}
const tradeValue=(t:Trade)=>t.quantity*t.price/(t.asset_type==='FUND'?10000:1)
const quantityLabel=(p:{quantity:number;asset_type:string})=>p.asset_type==='CASH'?formatYen(p.quantity):`${formatNum(p.quantity,p.asset_type==='FUND'?0:4)}${p.asset_type==='FUND'?'口':' 株'}`
const tradeLabel=(t:Trade)=>t.entry_type==='OPENING'?'開始残高':t.side==='BUY'?'買付':'売却'
const notify=(s:string)=>{toast.value=s;setTimeout(()=>{toast.value=''},3200)}
async function api<T>(path:string,init?:RequestInit):Promise<T>{const r=await fetch(`/api${path}`,{...init,headers:{'Content-Type':'application/json',...(init?.headers||{})}});const data=await r.json() as T & {error?:string};if(!r.ok)throw new Error(data.error||'処理に失敗しました');return data}
async function loadAll(){loading.value=true;try{const [t,p,q,s,settings]=await Promise.all([api<Trade[]>('/trades'),api<Position[]>('/positions'),api<Quote[]>('/quotes'),api<Snap[]>('/snapshots'),api<{hasApiKey:boolean}>('/settings')]);trades.value=t;positions.value=p;quotes.value=q;snapshots.value=s;keyState.value=settings.hasApiKey}catch(e){notify((e as Error).message)}finally{loading.value=false}}
async function scrollMarkets(){page.value='overview';await nextTick();document.getElementById('markets')?.scrollIntoView({behavior:'smooth'})}
async function refreshQuotes(){refreshing.value=true;try{const result=await api<{quotes:Quote[];errors:string[]}>('/quotes/refresh',{method:'POST',body:'{}'});quotes.value=result.quotes;snapshots.value=await api<Snap[]>('/snapshots');if(result.errors.length)notify(result.errors[0]);else notify('価格を更新しました')}catch(e){notify((e as Error).message)}finally{refreshing.value=false}}
function openAdd(){editing.value=null;form.value=blankForm();formError.value='';modal.value=true}
function openEdit(t:Trade){editing.value=t.id;form.value={symbol:t.symbol,name:t.name,market:t.market,currency:t.currency,side:t.side,trade_date:t.trade_date,quantity:String(t.quantity),price:String(t.price),fee:String(t.fee),target_price:t.target_price==null?'':String(t.target_price),asset_type:t.asset_type||'STOCK',entry_type:t.entry_type||'TRADE'};formError.value='';modal.value=true}
async function saveTrade(){formError.value='';try{const f=form.value;const body={...f,quantity:Number(f.quantity),price:Number(f.price),fee:Number(f.fee),target_price:f.target_price?Number(f.target_price):null};trades.value=await api<Trade[]>(editing.value?`/trades/${editing.value}`:'/trades',{method:editing.value?'PUT':'POST',body:JSON.stringify(body)});positions.value=await api<Position[]>('/positions');modal.value=false;notify(editing.value?'取引を更新しました':'取引を登録しました')}catch(e){formError.value=(e as Error).message}}
function selectAssetType(type:'STOCK'|'FUND'|'CASH'){form.value.asset_type=type;form.value.market='JP';form.value.currency='JPY';if(type==='FUND')form.value.symbol='FUND-';if(type==='CASH'){form.value.symbol='CASH_JPY';form.value.name='預り金（円）';form.value.quantity='';form.value.price='1';form.value.fee='0'}}
async function deleteTrade(id:number){if(!confirm('この取引を削除しますか？'))return;try{trades.value=await api<Trade[]>(`/trades/${id}`,{method:'DELETE'});positions.value=await api<Position[]>('/positions');notify('取引を削除しました')}catch(e){notify((e as Error).message)}}
async function storeKey(){try{const r=await api<{hasApiKey:boolean}>('/settings',{method:'PUT',body:JSON.stringify({apiKey:apiKey.value})});keyState.value=r.hasApiKey;apiKey.value='';settingsOpen.value=false;notify('APIキーを保存しました')}catch(e){notify((e as Error).message)}}
async function clearKey(){try{await api('/settings',{method:'PUT',body:JSON.stringify({clear:true})});keyState.value=false;apiKey.value='';notify('APIキーを削除しました')}catch(e){notify((e as Error).message)}}
function openPriceEditor(p:Position){pricePosition.value=p;manualPrice.value=String(quoteMap.value.get(`${p.symbol}:${p.currency}`)?.price??'');priceModal.value=true}
async function saveManualPrice(){try{const p=pricePosition.value;if(!p)return;const result=await api<{quotes:Quote[]}>('/quotes/manual',{method:'PUT',body:JSON.stringify({symbol:p.symbol,currency:p.currency,price:Number(manualPrice.value)})});quotes.value=result.quotes;snapshots.value=await api<Snap[]>('/snapshots');priceModal.value=false;notify('手動価格を更新しました')}catch(e){notify((e as Error).message)}}
function download(name:string,content:string,type='text/plain'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();URL.revokeObjectURL(a.href)}
function exportCsv(){const rows=[['symbol','name','market','currency','side','trade_date','quantity','price','fee','target_price','asset_type','entry_type'],...trades.value.map(t=>[t.symbol,t.name,t.market,t.currency,t.side,t.trade_date,t.quantity,t.price,t.fee,t.target_price??'',t.asset_type||'STOCK',t.entry_type||'TRADE'])];download('folio-trades.csv','\ufeff'+rows.map(r=>r.map(x=>`"${String(x).replaceAll('"','""')}"`).join(',')).join('\r\n'),'text/csv')}
function parseCsv(text:string){const lines=text.replace(/^\ufeff/,'').split(/\r?\n/).filter(Boolean);const parse=(s:string)=>{const a:string[]=[];let x='',quoted=false;for(let i=0;i<s.length;i++){if(s[i]==='"'&&s[i+1]==='"'&&quoted){x+='"';i++}else if(s[i]==='"')quoted=!quoted;else if(s[i]===','&&!quoted){a.push(x);x=''}else x+=s[i]}a.push(x);return a};const headers=parse(lines[0]).map(x=>x.trim());return lines.slice(1).map(line=>{const cells=parse(line);return Object.fromEntries(headers.map((h,i)=>[h,cells[i]??'']))})}
async function importCsv(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;try{const rows=parseCsv(await file.text()).map(row=>({...row,quantity:Number(row.quantity),price:Number(row.price),fee:Number(row.fee||0),target_price:row.target_price?Number(row.target_price):null,quote_price:row.quote_price?Number(row.quote_price):undefined}));if(!rows.length)throw new Error('CSVに取引行がありません');await api('/trades/import',{method:'POST',body:JSON.stringify({trades:rows})});await loadAll();notify(`${rows.length}件の取引を取り込みました`)}catch(e){notify((e as Error).message)}finally{(e.target as HTMLInputElement).value=''}}
async function exportBackup(){const b=await api<any>('/backup');download('folio-backup.json',JSON.stringify(b,null,2),'application/json')}
async function restoreBackup(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;if(!confirm('現在の取引・推移データを置き換えて復元しますか？'))return;try{const b=JSON.parse(await file.text());await api('/restore',{method:'POST',body:JSON.stringify(b)});await loadAll();notify('バックアップを復元しました')}catch(e){notify((e as Error).message)}finally{(e.target as HTMLInputElement).value=''}}
function downloadTemplate(){download('folio-template.csv','symbol,name,market,currency,side,trade_date,quantity,price,fee,target_price,asset_type,entry_type\n7203.T,トヨタ自動車,JP,JPY,BUY,2026-01-15,100,3200,0,3600,STOCK,TRADE\nAAPL,Apple,US,USD,BUY,2026-02-01,5,225,1,250,STOCK,TRADE\nFUND-SAMPLE,サンプル投信,JP,JPY,BUY,2026-01-15,50000,12000,0,,FUND,TRADE\n','text/csv')}
onMounted(loadAll)
</script>

<template>
 <div class="app-shell">
  <aside class="sidebar">
   <div class="brand"><div class="brand-mark"><span></span><span></span><span></span></div><span class="brand-name">folio<span class="brand-dot">.</span></span></div>
   <div class="workspace"><div class="avatar">Y</div><div><b>My portfolio</b><small>PERSONAL ACCOUNT</small></div><ChevronDown :size="15" class="muted-icon"/></div>
   <p class="nav-label">WORKSPACE</p>
   <nav><button :class="{active:page==='overview'}" @click="page='overview'"><LayoutDashboard :size="17"/>概要</button><button :class="{active:page==='holdings'}" @click="page='holdings'"><BriefcaseBusiness :size="17"/>保有資産 <span class="nav-count">{{holdingCount}}</span></button><button :class="{active:page==='activity'}" @click="page='activity'"><ArrowLeftRight :size="17"/>取引履歴</button></nav>
   <p class="nav-label market-nav-label">MARKETS</p><nav><button @click="scrollMarkets"><Globe2 :size="17"/>マーケット</button></nav>
   <div class="sidebar-bottom"><div class="privacy-note"><ShieldCheck :size="17"/><div><b>あなたの端末で安全に</b><p>ポートフォリオはローカルに保存されています。</p></div></div><button class="settings-nav" @click="settingsOpen=true"><Settings2 :size="17"/>設定</button><div class="user-row"><div class="user-avatar">Y</div><div><b>あなた</b><small>個人アカウント</small></div><MoreHorizontal :size="18" class="muted-icon"/></div></div>
  </aside>
  <main class="main-area">
   <header class="topbar"><div class="breadcrumbs"><span>マイワークスペース</span><ChevronRight :size="14"/><b>{{page==='holdings'?'保有資産':page==='activity'?'取引履歴':'概要'}}</b></div><div class="top-actions"><div class="market-open"><i></i>マーケット情報 <span>取得値</span></div><button class="icon-button" title="設定" @click="settingsOpen=true"><SlidersHorizontal :size="17"/></button><button class="avatar top-avatar">Y</button></div></header>
   <div class="content">
    <section class="welcome-row"><div><div class="eyebrow"><span></span>あなたの投資ダッシュボード</div><h1>{{page==='holdings'?'保有資産':page==='activity'?'取引履歴':'おかえりなさい'}}</h1><p class="subhead">{{page==='overview'?'資産の今を、ひと目で。':page==='holdings'?'保有銘柄の評価額とパフォーマンス。':'取引記録を整理して、資産の流れを把握。'}}</p></div><div class="header-buttons"><button class="button button-quiet" @click="exportBackup"><Download :size="16"/>バックアップ</button><button class="button button-dark" @click="openAdd"><Plus :size="16"/>取引を追加</button></div></section>
    <div class="notice-strip"><div class="notice-icon"><ShieldCheck :size="15"/></div><span>保有情報はこの端末内に保存されています。株価・為替は取得できた最新値で、リアルタイムではありません。</span><button @click="settingsOpen=true">データについて <ChevronRight :size="14"/></button></div>
    <section v-if="page==='overview'||page==='holdings'" class="summary-grid">
     <article class="summary-card hero-card"><div class="card-top"><span>総資産評価額</span><div class="icon-box pale-green"><Wallet :size="17"/></div></div><div class="value-row"><strong>{{formatYen(totalValue,true)}}</strong><span class="unit">JPY</span></div><div class="summary-foot"><span class="change-pill" :class="totalPnl>=0?'positive':'negative'"><component :is="totalPnl>=0?ArrowUpRight:ArrowDownRight" :size="14"/>{{totalPnl>=0?'+':''}}{{formatYen(totalPnl,true)}}</span><span class="foot-copy">取得額からの損益</span></div><div class="hero-spark"><svg viewBox="0 0 150 48" preserveAspectRatio="none"><path d="M0 37 C14 34 17 38 28 29 S46 33 56 23 S74 32 86 18 S100 23 111 15 S130 23 150 5"/><path class="spark-fill" d="M0 37 C14 34 17 38 28 29 S46 33 56 23 S74 32 86 18 S100 23 111 15 S130 23 150 5 L150 48 L0 48Z"/></svg></div></article>
     <article class="summary-card"><div class="card-top"><span>トータルリターン</span><div class="icon-box pale-purple"><TrendingUp :size="17"/></div></div><div class="value-row"><strong :class="totalPnl>=0?'ink-green':'ink-red'">{{totalPnl>=0?'+':''}}{{formatYen(totalPnl,true)}}</strong></div><div class="summary-foot"><span class="change-pill" :class="totalPct>=0?'positive':'negative'"><component :is="totalPct>=0?ArrowUpRight:ArrowDownRight" :size="14"/>{{totalPct>=0?'+':''}}{{formatNum(totalPct)}}%</span><span class="foot-copy">取得総額比</span></div><div class="card-decoration decor-purple"><div></div><div></div><div></div></div></article>
     <article class="summary-card"><div class="card-top"><span>保有銘柄</span><div class="icon-box pale-blue"><BriefcaseBusiness :size="17"/></div></div><div class="value-row"><strong>{{holdingCount}}<small class="inline-unit"> 銘柄</small></strong></div><div class="summary-foot"><span class="dot-marker"></span><span class="foot-copy">{{computedPositions.filter(p=>p.market==='JP').length}} 国内 · {{computedPositions.filter(p=>p.market==='US').length}} 米国</span></div><div class="card-decoration decor-blue"><div></div><div></div><div></div><div></div></div></article>
     <article class="summary-card fx-card"><div class="card-top"><span>為替レート</span><div class="icon-box pale-orange"><ArrowLeftRight :size="17"/></div></div><div class="fx-big">{{fx?formatNum(fx,2):'—'}}<small> JPY</small></div><div class="summary-foot"><span class="currency-pair">USD <ArrowLeftRight :size="11"/> JPY</span><span class="foot-copy">{{fx?since(quoteMap.get('USD/JPY:FX')?.fetched_at||''):'未取得'}}</span></div><div class="fx-wave"><svg viewBox="0 0 130 36" preserveAspectRatio="none"><path d="M0 25 Q11 28 19 21T38 23T57 15T77 21T99 10T130 8"/></svg></div></article>
    </section>
    <section v-if="page==='overview'||page==='holdings'" class="main-grid">
     <article class="panel chart-panel"><div class="panel-heading"><div><h2>資産推移</h2><p>記録した日次スナップショット · JPY</p></div><div class="period-switch"><button v-for="p in ['1W','1M','3M','1Y','ALL']" :key="p" :class="{selected:period===p}" @click="period=p">{{p}}</button></div></div>
      <div class="chart-big-row"><strong>{{formatYen(totalValue)}}</strong><span v-if="chartPoints.length>1" :class="chartChange>=0?'chart-positive':'chart-negative'"><component :is="chartChange>=0?ArrowUpRight:ArrowDownRight" :size="15"/>{{chartChange>=0?'+':''}}{{formatYen(chartChange)}}</span><span v-else class="chart-empty-hint">記録が増えるとここに推移が表示されます</span></div>
      <div v-if="chartPoints.length>1" class="chart-wrap"><div class="chart-y"><span>{{formatYen(Math.max(...chartPoints.map(x=>x.value_jpy)),true)}}</span><span>{{formatYen((Math.max(...chartPoints.map(x=>x.value_jpy))+Math.min(...chartPoints.map(x=>x.value_jpy)))/2,true)}}</span><span>{{formatYen(Math.min(...chartPoints.map(x=>x.value_jpy)),true)}}</span></div><svg viewBox="0 0 100 100" preserveAspectRatio="none" class="portfolio-chart"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#6a9a76" stop-opacity=".19"/><stop offset="100%" stop-color="#6a9a76" stop-opacity="0"/></linearGradient></defs><path :d="chartArea" fill="url(#area)"/><path :d="chartPath" fill="none" stroke="#638a6c" stroke-width=".72" vector-effect="non-scaling-stroke" stroke-linecap="round" stroke-linejoin="round"/></svg><div class="chart-x"><span>{{formatDate(chartPoints[0]?.day||'')}}</span><span>{{formatDate(chartPoints[Math.floor(chartPoints.length/2)]?.day||'')}}</span><span>{{formatDate(chartPoints.at(-1)?.day||'')}}</span></div></div>
      <div v-else class="chart-placeholder"><div class="placeholder-grid"><div v-for="n in 4" :key="n"></div></div><div class="placeholder-zero"><div class="placeholder-icon"><Activity :size="20"/></div><b>資産の記録を始めましょう</b><span>価格を更新すると、今日のスナップショットを保存します。</span><button class="text-action" @click="refreshQuotes" :disabled="refreshing"><LoaderCircle v-if="refreshing" :size="14" class="spin"/><Activity v-else :size="14"/>価格を更新して記録</button></div><div class="chart-x"><span>記録開始</span><span></span><span>今日</span></div></div>
      <div class="chart-bottom"><div class="legend"><span></span>ポートフォリオ評価額</div><div class="chart-meta"><Clock3 :size="13"/> {{snapshots.length?`最終記録 ${formatDate(snapshots.at(-1)!.day)}`:'記録なし'}}</div></div>
     </article>
     <article class="panel allocation-panel"><div class="panel-heading"><div><h2>ポートフォリオ構成</h2><p>評価額の内訳</p></div><button class="more-button" @click="page='holdings'"><MoreHorizontal :size="19"/></button></div><div v-if="computedPositions.length" class="allocation-body"><div class="donut" :style="donutStyle"><div class="donut-center"><b>{{computedPositions.length}}</b><span>銘柄</span></div></div><div class="allocation-list"><div v-for="(p,i) in [...computedPositions].sort((a,b)=>b.value-a.value).slice(0,4)" :key="p.symbol" class="allocation-row"><i :style="{background:colors[i%colors.length]}"></i><span class="alloc-name">{{p.name}}</span><b>{{totalValue?formatNum((p.value*(p.currency==='USD'?fx:1))/totalValue*100,0):0}}%</b></div></div></div><div v-else class="allocation-empty"><div class="allocation-empty-donut"></div><p>取引を登録すると<br>構成比が表示されます</p></div><button class="allocation-link" @click="page='holdings'">保有資産を見る <ChevronRight :size="14"/></button></article>
    </section>
    <section v-if="page==='overview'||page==='holdings'" class="panel holdings-panel"><div class="table-heading"><div><h2>{{page==='holdings'?'保有資産':'保有銘柄'}}</h2><p>現在のパフォーマンスと評価額</p></div><div class="table-tools"><label class="search-box"><Search :size="15"/><input v-model="search" placeholder="銘柄を検索"/></label><button class="button button-outline" @click="csvInput?.click()"><Upload :size="14"/> CSV取り込み</button><input ref="csvInput" type="file" accept=".csv,text/csv" hidden @change="importCsv"/><button class="button button-outline" @click="exportCsv"><Download :size="14"/> CSV出力</button><button v-if="page==='overview'" class="button button-mini-dark" @click="openAdd"><Plus :size="15"/>追加</button></div></div>
      <div class="table-scroll"><table><thead><tr><th>銘柄</th><th>市場</th><th>保有数量</th><th>平均取得単価</th><th>現在値 <button class="refresh-inline" @click="refreshQuotes" :disabled="refreshing" :title="'更新 · '+since(capturedAt)"><LoaderCircle v-if="refreshing" :size="12" class="spin"/><Activity v-else :size="12"/></button></th><th>評価額</th><th>損益</th><th></th></tr></thead><tbody><tr v-for="p in filtered.slice(0,page==='overview'?5:100)" :key="p.symbol"><td><div class="asset-cell"><div class="asset-logo" :class="p.market==='US'?'logo-us':'logo-jp'">{{p.symbol.slice(0,1)}}</div><div><b>{{p.name}}</b><small>{{p.symbol}}</small></div></div></td><td><span class="market-badge" :class="p.market==='JP'?'badge-jp':'badge-us'">{{p.asset_type==='FUND'?'投資信託':p.asset_type==='CASH'?'現金':p.market==='JP'?'🇯🇵 東証':'🇺🇸 US'}}</span></td><td class="num-cell">{{quantityLabel(p)}}</td><td class="num-cell">{{formatMoney(p.average_cost,p.currency)}}</td><td class="num-cell"><b>{{p.price?formatMoney(p.price,p.currency):'—'}}</b><small class="quote-age">{{p.quote?since(p.quote.fetched_at):'未取得'}}</small></td><td class="num-cell"><b>{{p.price?formatMoney(p.value,p.currency):'—'}}</b></td><td class="num-cell"><span :class="p.pnl>=0?'positive-text':'negative-text'">{{p.price?`${p.pnl>=0?'+':''}${formatMoney(p.pnl,p.currency)} (${p.pct>=0?'+':''}${formatNum(p.pct)}%)`:'—'}}</span><small v-if="p.target_price&&p.price" class="quote-age" :class="p.target_price>=p.price?'positive-text':'negative-text'">目標まで {{p.target_price>=p.price?'+':''}}{{formatNum((p.target_price-p.price)/p.price*100)}}%</small></td><td><button v-if="p.asset_type!=='STOCK'" class="row-action" :title="p.name+'の価格を更新'" @click="openPriceEditor(p)"><SlidersHorizontal :size="14"/></button><button v-else class="row-action" :title="p.name+'の取引を追加'" @click="form={...blankForm(),symbol:p.symbol,name:p.name,market:p.market,currency:p.currency,side:'BUY'};editing=null;modal=true"><Plus :size="15"/></button></td></tr><tr v-if="!filtered.length"><td colspan="8"><div class="empty-table"><div class="empty-art"><Wallet :size="22"/></div><b>最初の取引を登録しましょう</b><span>買った銘柄や取引履歴を登録すると、資産状況がここに表示されます。</span><button class="button button-dark" @click="openAdd"><Plus :size="15"/>取引を追加</button><a @click="downloadTemplate">CSVテンプレートをダウンロード</a></div></td></tr></tbody></table></div>
      <div v-if="page==='overview'&&filtered.length>5" class="table-footer"><span>全{{filtered.length}}銘柄中 5銘柄を表示</span><button @click="page='holdings'">すべての保有資産を見る <ArrowUpRight :size="14"/></button></div>
     </section>
     <section v-if="page==='overview'" id="markets" class="market-section"><div class="section-title"><div><div class="eyebrow"><span></span>GLOBAL MARKETS</div><h2>マーケット概況</h2><p>株式市場の参考指標と為替レート</p></div><button class="button button-quiet" @click="refreshQuotes" :disabled="refreshing"><LoaderCircle v-if="refreshing" :size="15" class="spin"/><Activity v-else :size="15"/>価格を更新</button></div>
      <div class="market-grid"><article v-for="m in markets" :key="m.symbol" class="market-card"><div class="market-card-head"><span class="flag">{{m.flag}}</span><div><b>{{m.name}}</b><small>{{m.region}}</small></div><button title="価格を更新" @click="refreshQuotes"><ExternalLink :size="14"/></button></div><div class="market-price">{{quoteMap.get(`${m.symbol}:USD`)?formatMoney(quoteMap.get(`${m.symbol}:USD`)!.price,'USD'):'—'}}</div><div class="market-card-foot"><span v-if="quoteMap.get(`${m.symbol}:USD`)?.change_pct!=null" :class="quoteMap.get(`${m.symbol}:USD`)!.change_pct!>=0?'positive-text':'negative-text'"><component :is="quoteMap.get(`${m.symbol}:USD`)!.change_pct!>=0?ArrowUpRight:ArrowDownRight" :size="14"/>{{formatNum(quoteMap.get(`${m.symbol}:USD`)!.change_pct!)}}%</span><span v-else class="missing-quote">価格は未取得</span><small>ETF参考値 · {{quoteMap.get(`${m.symbol}:USD`)?since(quoteMap.get(`${m.symbol}:USD`)!.fetched_at):'—'}}</small></div></article></div><div class="fx-market-strip"><div class="fx-strip-label"><ArrowLeftRight :size="14"/><span>為替レート</span><small>対日本円 · 取得値</small></div><div v-for="pair in ['USD/JPY','EUR/JPY','GBP/JPY','AUD/JPY']" :key="pair" class="fx-quote"><span>{{pair}}</span><b>{{quoteMap.get(`${pair}:FX`)?formatNum(quoteMap.get(`${pair}:FX`)!.price,2):'—'}}</b><small v-if="quoteMap.get(`${pair}:FX`)?.change_pct!=null" :class="quoteMap.get(`${pair}:FX`)!.change_pct!>=0?'positive-text':'negative-text'">{{quoteMap.get(`${pair}:FX`)!.change_pct!>=0?'+':''}}{{formatNum(quoteMap.get(`${pair}:FX`)!.change_pct!)}}%</small><small v-else class="fx-no-change">JPY</small></div></div>
      <div class="market-footnote"><CircleHelp :size="14"/>SPY・QQQ・EWJ・VGKのETF価格を各地域の参考指標として表示します。株価データには遅延や提供範囲の制限があります。 <button @click="settingsOpen=true">データ設定 <ChevronRight :size="12"/></button></div>
     </section>
     <section v-if="page==='overview'" class="bottom-grid"><article class="panel activity-panel"><div class="panel-heading"><div><h2>最近の取引</h2><p>ポートフォリオの動き</p></div><button class="inline-link" @click="page='activity'">すべて見る <ArrowUpRight :size="14"/></button></div><div v-if="filteredTrades.length" class="activity-list"><div v-for="t in filteredTrades.slice(0,4)" :key="t.id" class="activity-row"><div class="activity-logo" :class="t.market==='JP'?'logo-jp':'logo-us'">{{t.symbol.slice(0,1)}}</div><div class="activity-info"><b>{{t.name}}</b><small>{{t.symbol}} · {{formatDate(t.trade_date)}}</small></div><span class="side-badge" :class="t.side==='BUY'?'side-buy':'side-sell'">{{tradeLabel(t)}}</span><div class="activity-value"><b>{{formatMoney(tradeValue(t),t.currency)}}</b><small>{{quantityLabel({quantity:t.quantity,asset_type:t.asset_type})}}</small></div></div></div><div v-else class="activity-empty"><CalendarDays :size="19"/>取引履歴はまだありません</div></article><article class="insight-card"><div class="insight-glow"></div><div class="insight-head"><div class="insight-icon"><Sparkles :size="16"/></div><span>PORTFOLIO INSIGHT</span></div><h3>{{holdingCount?'投資の全体像を<br>チェックしましょう':'自分の資産を<br>ひとつの場所に。'}}</h3><p>{{holdingCount?'保有銘柄の目標価格を設定すると、価格との差を一覧で確認できます。AIによる投資判断は行いません。':'買付価格や数量を登録するだけで、損益や円換算の評価額をまとめて確認できます。'}}</p><button @click="holdingCount?(page='holdings'):openAdd()">{{holdingCount?'保有資産を確認':'最初の取引を登録'}} <ArrowUpRight :size="14"/></button><div class="insight-squiggle"><svg viewBox="0 0 160 65" preserveAspectRatio="none"><path d="M0 57 Q18 50 29 42 T51 39 T72 25 T93 32 T112 16 T135 20 T160 3"/></svg></div></article></section>
    <section v-if="page==='activity'" class="panel activity-table-panel"><div class="table-heading"><div><h2>取引履歴</h2><p>買付・売却の記録 {{trades.length}}件</p></div><div class="table-tools"><button class="button button-outline" @click="csvInput?.click()"><Upload :size="14"/> CSV取り込み</button><button class="button button-outline" @click="exportCsv"><Download :size="14"/> CSV出力</button><button class="button button-dark" @click="openAdd"><Plus :size="15"/>取引を追加</button></div></div><div class="table-scroll"><table><thead><tr><th>銘柄</th><th>売買</th><th>取引日</th><th>数量</th><th>約定価格</th><th>手数料</th><th>取引金額</th><th></th></tr></thead><tbody><tr v-for="t in trades" :key="t.id" @click="openEdit(t)" class="clickable-row"><td><div class="asset-cell"><div class="asset-logo" :class="t.market==='US'?'logo-us':'logo-jp'">{{t.symbol.slice(0,1)}}</div><div><b>{{t.name}}</b><small>{{t.symbol}}</small></div></div></td><td><span class="side-badge" :class="t.side==='BUY'?'side-buy':'side-sell'">{{tradeLabel(t)}}</span></td><td>{{formatDate(t.trade_date)}}</td><td class="num-cell">{{quantityLabel({quantity:t.quantity,asset_type:t.asset_type})}}</td><td class="num-cell">{{formatMoney(t.price,t.currency)}}</td><td class="num-cell">{{formatMoney(t.fee,t.currency)}}</td><td class="num-cell"><b>{{formatMoney(tradeValue(t),t.currency)}}</b></td><td><button class="row-action" @click.stop="deleteTrade(t.id)" title="削除"><X :size="14"/></button></td></tr><tr v-if="!trades.length"><td colspan="8"><div class="empty-table"><div class="empty-art"><ArrowLeftRight :size="22"/></div><b>取引データがありません</b><span>最初の売買を記録して、資産推移をつけましょう。</span><button class="button button-dark" @click="openAdd"><Plus :size="15"/>取引を追加</button></div></td></tr></tbody></table></div></section>
    <footer class="app-footer"><span>folio <i>·</i> 個人資産ダッシュボード</span><span><ShieldCheck :size="13"/> ローカル保存 <i>·</i> 市場データは参考情報です</span></footer>
   </div>
  </main>
  <div v-if="modal" class="modal-backdrop" @click.self="modal=false"><section class="modal-card"><div class="modal-head"><div><div class="eyebrow"><span></span>{{editing?'取引を編集':'PORTFOLIO ACTIVITY'}}</div><h2>{{editing?'取引を編集':'取引を追加'}}</h2></div><button class="icon-button" @click="modal=false"><X :size="18"/></button></div><p class="modal-copy">買付や売却の内容を記録します。取得価格と数量はあとから編集できます。</p><div class="asset-kind-toggle"><button :class="{chosen:form.asset_type==='STOCK'}" @click="selectAssetType('STOCK')">株式</button><button :class="{chosen:form.asset_type==='FUND'}" @click="selectAssetType('FUND')">投資信託</button><button :class="{chosen:form.asset_type==='CASH'}" @click="selectAssetType('CASH')">現金残高</button></div><div v-if="form.asset_type!=='CASH'" class="side-toggle"><button :class="{chosen:form.side==='BUY'}" @click="form.side='BUY'">買付</button><button :class="{chosen:form.side==='SELL'}" @click="form.side='SELL'">売却</button></div><div class="form-grid"><label class="wide">銘柄コード<input v-model="form.symbol" placeholder="例: 7203.T / AAPL" autocomplete="off"/></label><label class="wide">銘柄名<input v-model="form.name" placeholder="例: トヨタ自動車"/></label><label>市場<select v-model="form.market" :disabled="form.asset_type!=='STOCK'" @change="form.currency=form.market==='JP'?'JPY':'USD'"><option value="JP">日本株 · 東証</option><option value="US">米国株 · US</option></select></label><label>通貨<select v-model="form.currency"><option value="JPY">JPY · 日本円</option><option value="USD">USD · 米ドル</option></select></label><label>取引日<input v-model="form.trade_date" type="date"/></label><label>{{form.asset_type==='FUND'?'数量（口）':form.asset_type==='CASH'?'口数':'数量（株）'}}<input v-model="form.quantity" type="number" step="any" min="0" :placeholder="form.asset_type==='FUND'?'50,000':'100'" :disabled="form.asset_type==='CASH'"/></label><label>{{form.asset_type==='FUND'?'価格（1万口あたり）':form.asset_type==='CASH'?'預り金額':'約定価格'}}<input v-model="form.price" type="number" step="any" min="0" :placeholder="form.asset_type==='FUND'?'22,300':'3,250'"/></label><label>手数料<input v-model="form.fee" type="number" step="any" min="0" placeholder="0"/></label><label class="wide">目標価格 <small class="optional">任意 · 売却判断の参考用</small><input v-model="form.target_price" type="number" step="any" min="0" placeholder="設定すると目標との差を確認できます"/></label></div><div v-if="formError" class="form-error">{{formError}}</div><div class="modal-foot"><span><ShieldCheck :size="14"/> この記録は端末内に保存</span><div><button class="button button-quiet" @click="modal=false">キャンセル</button><button class="button button-dark" @click="saveTrade"><Check :size="15"/>{{editing?'変更を保存':'取引を保存'}}</button></div></div></section></div>
  <div v-if="settingsOpen" class="modal-backdrop" @click.self="settingsOpen=false"><section class="modal-card settings-modal"><div class="modal-head"><div><div class="eyebrow"><span></span>LOCAL CONFIGURATION</div><h2>データ設定</h2></div><button class="icon-button" @click="settingsOpen=false"><X :size="18"/></button></div><p class="modal-copy">Alpha VantageのAPIキーを登録して、株価と為替を取得します。キーはこの端末のローカルSQLiteに保存します。</p><div class="provider-card"><div class="provider-logo">AV</div><div><b>Alpha Vantage</b><small>無料枠 · 1日25リクエスト · 最新の提供値</small></div><span class="provider-status" :class="keyState?'is-connected':''"><i></i>{{keyState?'設定済み':'未設定'}}</span></div><label class="settings-label">APIキー<input v-model="apiKey" type="password" placeholder="APIキーを入力" autocomplete="new-password"/></label><div class="settings-actions"><a href="https://www.alphavantage.co/support/#api-key" target="_blank" rel="noreferrer">無料APIキーを取得 <ExternalLink :size="13"/></a><button class="button button-dark" @click="storeKey"><Check :size="15"/>保存</button></div><div class="settings-divider"></div><div class="settings-block"><div><b>ポートフォリオのバックアップ</b><small>取引履歴と日次評価額をJSON形式で保存・復元</small></div><div class="settings-actions"><button class="button button-outline" @click="exportBackup"><Download :size="14"/>書き出す</button><button class="button button-outline" @click="backupInput?.click()"><FileUp :size="14"/>復元</button><input ref="backupInput" type="file" accept=".json,application/json" hidden @change="restoreBackup"/></div></div><div class="settings-disclaimer"><CircleHelp :size="15"/><p>このダッシュボードは記録・参考情報を表示します。投資助言や売買推奨ではありません。価格の鮮度は提供元や無料枠により異なります。</p></div><button v-if="keyState" class="clear-key" @click="clearKey">APIキーを削除</button></section></div>
  <div v-if="priceModal&&pricePosition" class="modal-backdrop" @click.self="priceModal=false"><section class="modal-card price-modal"><div class="modal-head"><div><div class="eyebrow"><span></span>MANUAL MARKET PRICE</div><h2>基準価格を更新</h2></div><button class="icon-button" @click="priceModal=false"><X :size="18"/></button></div><p class="modal-copy">{{pricePosition.name}}の価格を手動で更新します。投資信託は1万口あたりの基準価額、現金は残高を入力してください。</p><label class="settings-label">{{pricePosition.asset_type==='FUND'?'基準価額（1万口あたり）':'円残高'}}<input v-model="manualPrice" type="number" step="any" min="0"/></label><div class="modal-foot"><span><Clock3 :size="14"/> 更新日時を記録します</span><div><button class="button button-quiet" @click="priceModal=false">キャンセル</button><button class="button button-dark" @click="saveManualPrice"><Check :size="15"/>価格を保存</button></div></div></section></div>
  <Transition name="toast"><div v-if="toast" class="toast"><Check :size="16"/>{{toast}}</div></Transition>
 </div>
</template>
